"""Add playback components to the Android shell generated by the APK workflow."""
from pathlib import Path
import xml.etree.ElementTree as ET

android_namespace = "http://schemas.android.com/apk/res/android"
ET.register_namespace("android", android_namespace)


def android(name):
    return f"{{{android_namespace}}}{name}"


manifest = Path("android/app/src/main/AndroidManifest.xml")
tree = ET.parse(manifest)
root = tree.getroot()
app = root.find("application")
for permission in (
    "android.permission.FOREGROUND_SERVICE",
    "android.permission.FOREGROUND_SERVICE_MEDIA_PLAYBACK",
    "android.permission.WAKE_LOCK",
):
    root.insert(0, ET.Element("uses-permission", {android("name"): permission}))

activity = next(
    item for item in app.findall("activity")
    if item.get(android("name")) == ".MainActivity"
)
activity.set(android("supportsPictureInPicture"), "true")

service = ET.SubElement(app, "service", {
    android("name"): ".MediaPlaybackService",
    android("exported"): "true",
    android("foregroundServiceType"): "mediaPlayback",
})
ET.SubElement(ET.SubElement(service, "intent-filter"), "action", {
    android("name"): "androidx.media3.session.MediaSessionService",
})
receiver = ET.SubElement(app, "receiver", {
    android("name"): "androidx.media3.session.MediaButtonReceiver",
    android("exported"): "true",
})
ET.SubElement(ET.SubElement(receiver, "intent-filter"), "action", {
    android("name"): "android.intent.action.MEDIA_BUTTON",
})
tree.write(manifest, encoding="utf-8", xml_declaration=True)

# video_player_android on the current Flutter dependency graph already uses this
# version of ExoPlayer. The app owns the single Android player through Media3.
gradle = Path("android/app/build.gradle.kts")
with gradle.open("a", encoding="utf-8") as target:
    target.write(
        '\ndependencies {\n'
        '    implementation("androidx.media3:media3-exoplayer:1.9.2")\n'
        '    implementation("androidx.media3:media3-session:1.9.2")\n'
        '}\n'
    )
